import { lazy } from 'react';
import { CalendarDays as IcCalendarDays, PenLine as IcPenLine, Plane as IcPlane, Send as IcSend, Ticket as IcTicket, Wallet as IcWallet } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * My Travel — hub page for the Travel Desk menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 5 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'MyTravel'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const TravelEntry = lazy(() => import('./TravelEntry'));
const TravelRequests = lazy(() => import('./TravelRequests'));
const TravelBookings = lazy(() => import('./TravelBookings'));
const TravelAdvances = lazy(() => import('./TravelAdvances'));
const TravelCalendar = lazy(() => import('./TravelCalendar'));

export const TABS = [
  { id: 'entry', label: 'Travel Entry', icon: IcPenLine, page: 'TravelEntry', Component: TravelEntry },
  { id: 'requests', label: 'Travel Requests', icon: IcSend, page: 'TravelRequests', Component: TravelRequests },
  { id: 'bookings', label: 'Bookings', icon: IcTicket, page: 'TravelBookings', Component: TravelBookings },
  { id: 'advances', label: 'Advances', icon: IcWallet, page: 'TravelAdvances', Component: TravelAdvances },
  { id: 'calendar', label: 'Travel Calendar', icon: IcCalendarDays, page: 'TravelCalendar', Component: TravelCalendar },
];

export default function MyTravel({ setPage }) {
  return (
    <TabHub
      icon={IcPlane}
      eyebrow="Travel Desk"
      title="My Travel"
      subtitle="Log a trip, raise a request, book it, draw an advance and see your calendar"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
